patch:
diff --git a/src/classic/avdtp_initiator.c b/src/classic/avdtp_initiator.c
index 36055e4e4..13b3a9402 100644
--- a/src/classic/avdtp_initiator.c
+++ b/src/classic/avdtp_initiator.c
@@ -79,6 +79,14 @@ void avdtp_initiator_stream_config_subsm(avdtp_connection_t *connection, uint8_t
     avdtp_stream_endpoint_t * stream_endpoint_for_event = NULL;

     avdtp_sep_t sep;
+    /* A delayed/duplicate reply cannot retire another outstanding transaction. */
+    if (connection->initiator_signaling_packet.transaction_label !=
+        connection->initiator_transaction_label) {
+        log_info("stale AVDTP response label %u (expected %u)",
+                 connection->initiator_signaling_packet.transaction_label,
+                 connection->initiator_transaction_label);
+        return;
+    }
     if (connection->initiator_connection_state == AVDTP_SIGNALING_CONNECTION_INITIATOR_W4_ANSWER) {
         connection->initiator_connection_state = AVDTP_SIGNALING_CONNECTION_INITIATOR_IDLE;
     } else {
@@ -273,9 +281,11 @@ void avdtp_initiator_stream_config_subsm(avdtp_connection_t *connection, uint8_t
             }
+            /* A synchronous accept callback may queue/send a new command.
+               Retire this label BEFORE calling out, not after the new send. */
+            connection->initiator_transaction_label = avdtp_get_next_transaction_label();
             if (stream_endpoint_for_event != NULL){
                 avdtp_signaling_emit_accept_for_stream_endpoint(stream_endpoint_for_event, connection->initiator_local_seid,
                                                                 connection->initiator_signaling_packet.signal_identifier, true);
             } else {
                 avdtp_signaling_emit_accept(connection->avdtp_cid, 0, connection->initiator_signaling_packet.signal_identifier, true);
             }
-            connection->initiator_transaction_label = avdtp_get_next_transaction_label();
             break;
@@ -284,6 +294,23 @@ void avdtp_initiator_stream_config_subsm(avdtp_connection_t *connection, uint8_t
                 case AVDTP_SI_SET_CONFIGURATION:
                     connection->configuration_state = AVDTP_CONFIGURATION_STATE_IDLE;
                     sep.in_use = 0;
+                    /* usbpods PATCH: a SET_CONFIGURATION reject carries the
+                       SERVICE CATEGORY the sink objected to plus an AVDTP
+                       error code, and stock BTstack drops both â€” leaving
+                       "Rejected AVDTP_SI_SET_CONFIGURATION" and pure guesswork
+                       about which field a headset disliked. Print them.
+                       category 0x07 = MEDIA_CODEC, 0x04 = CONTENT_PROTECTION;
+                       error 0x29 INVALID_CAPABILITIES, 0x2B NOT_SUPPORTED_CODEC,
+                       0x35 INVALID_OBJECT_TYPE, 0x39 INVALID_BIT_RATE,
+                       0x3A INVALID_SAMPLING_FREQUENCY, 0x3E INVALID_CHANNELS. */
+                    {
+                        extern int printf(const char *, ...);
+                        printf("AVDTP reject raw: size %u offset %d pkt_type %u :",
+                               size, offset,
+                               (unsigned) connection->initiator_signaling_packet.packet_type);
+                        for (uint16_t ri = 0; ri < size && ri < 12; ri++) printf(" %02x", packet[ri]);
+                        printf("\n");
+                    }
                     log_info("Received reject for set configuration, role changed from initiator to acceptor. TODO: implement retry.");
                     break;
                 case AVDTP_SI_RECONFIGURE:
